# first model: CAP-IRES - setup the sequences and protein objects
amanda_IRES = ''''''
amanda_CAP = ''''''
poi_0 = rsnp.seqmanip.seq_to_CDS_obj(amanda_IRES)
poi_1 = rsnp.seqmanip.seq_to_CDS_obj(amanda_CAP)

cap = poi_1['0'][0]
ires = poi_0['0'][0]

full_construct =amanda_CAP +  amanda_IRES
kelong = rsnp.propf.get_k( full_construct, .03, 1.7, 0)[1:]
kelong[1885] = 0  # Cap stop codon
kelong[-2] = 0 #IRES stop codon
IRES_start = 1886

# model parameters from the paper
k_init_cap = 4.8e-2
k_init_ires = 4.9e-2

k_on_c = 4.8e-4
k_off_c = 2e-3
k_on_i = 1.8e-4
k_off_i = 6.6e-3
k_on_ic = 1.5e-3

kout_cap = 1.7
kout_ires = 1.7


flagtags = cap.tag_epitopes
suntags = ires.tag_epitopes

probe_locations = np.zeros([2,len(kelong)], dtype=np.intc  )
probe_locations[0,flagtags['T_Flag']] = 1
probe_locations[1,np.array([suntags['T_SunTag']]) + IRES_start   ] = 1




probe_locations = np.zeros([2,len(kelong)], dtype=np.intc  )
probe_locations[0,flagtags['T_Flag']] = 1
probe_locations[1,np.array([suntags['T_SunTag']]) + IRES_start   ] = 1



# Make the mRNA object
full_construct = amanda_CAP +  amanda_IRES
poi = rsnp.seqmanip.seq_to_CDS_obj(full_construct) # convert a given sequence to a protein of interest object
mRNA = poi['0'][0]                              # pull out the main open reading frame

# patch to fix protein detection bug with this construct, will fix
mRNA.nt_seq = full_construct
mRNA.aa_seq = rsnp.seqmanip.nt2aa(full_construct)
mRNA.total_length = len(mRNA.aa_seq )
mRNA.tag_types =  ['T_Flag','T_SunTag']
mRNA.tag_epitopes = {'T_Flag': [1,10,19, 195, 205,217, 227,299,308,317],
   'T_SunTag': [1895,1919,1943,1967,1991,2015,2039,2063,2087,2111,2135,2159,2183, 2207, 2231, 2255, 2279, 2303, 2327, 2351,2375,2399,2447]}


mRNA_length = len(kelong)                  # get the length of the mRNA
mRNA.generate_3frame_tags()                     # call to generate all open reading frames tags
mRNA.multiframe_epitopes = [{'T_Flag': [1, 10, 19, 195, 205, 217, 227, 299, 308, 317],
                             'T_SunTag':[1895, 1919, 1943, 1967, 1991, 2015, 2039, 2063, 2087, 2111, 2135, 2159, 2183, 2207, 2231, 2255, 2279, 2303, 2327, 2351, 2375, 2399, 2447]}, {},{}]



model = rsnp.tasep_model(mRNA, 'dropoff') # model object
# Make the kelong mat (manually adding an extra location that is equal to zero, so particles dont run over the simulation)
kelong_mat = np.zeros([3, mRNA_length+1])
kelong_mat[0, :-2] = rsnp.propf.get_k(mRNA.nt_seq, .01, 3, 3)[1:-1]
kelong_mat[1, :-3] = rsnp.propf.get_k(mRNA.nt_seq[1:-2], .1, 3, 3)[1:-1]
kelong_mat[2, :-3] = rsnp.propf.get_k(mRNA.nt_seq[2:-1], .1, 3, 3)[1:-1]
kelong_mat[0, -2] = 0
kelong_mat[0,1885] = 0
kelong_mat[0,3351] = 0
model._kelong_mat = kelong_mat #override the current kelongation mat


probe_mat = np.zeros([3, mRNA_length+1])
probe_mat[0, [1,10,19, 195, 205,217, 227,299,308,317]] = 1
probe_mat[0, [1895,1919,1943,1967,1991,2015,2039,2063,2087,2111,2135,2159,2183, 2207, 2231, 2255, 2279, 2303, 2327, 2351,2375,2399,2447]] = 2
model._probe_mat = probe_mat #override the current kelongation mat

############ resources ####################


############ states ####################

# we need 4 states for cap ires
model.add_states(2, state0=[0,0], names=['cap','IRES'])


# ribosomal initiation CAP
footprint = 9
# first add the reaction, in this case, we want a lattice reaction at the first
# location for a ribosome to bind (excluded)
init = lambda k,t,p,ke,o,l,pr,s,r,nr: ~np.any(l[0:0+footprint])*k*s[0]
model.add_lattice_reaction(init, k_init_cap, rxn_name='initiation_cap', exclusion=1, frame=0, loc=0, dexist=1)

# ribosomal initiation IRES
# first add the reaction, in this case, we want a lattice reaction at the first
# location for a ribosome to bind (excluded)
init_ires = lambda k,t,p,ke,o,l,pr,s,r,nr: ~np.any(l[1886:1886+footprint])*k*s[1]
model.add_lattice_reaction(init_ires, k_init_ires, rxn_name='initiation_ires', exclusion=1, frame=0, loc=1886, dexist=1,)

# Now we need a reaction for ribosomes to leave the lattice frame 0 at the end (location 1885)
leave_cap = lambda k,t,p,ke,o,l,pr,s,r,nr: l[1885]*k #(lattice location 1084 = 1) * parameter
model.add_lattice_reaction(leave_cap, kout_cap, rxn_name='termination_cap', exclusion=0, frame=0, loc=1885, dexist=-1,)

# Now we need a reaction for ribosomes to leave the lattice frame 1 at the end (location 3351)
leave_ires = lambda k,t,p,ke,o,l,pr,s,r,nr: l[3351]*k #(lattice location 1084 = 1) * parameter
model.add_lattice_reaction(leave_ires, kout_ires, rxn_name='termination_ires', exclusion=0, frame=0, loc=3351, dexist=-1,)

############ STATE RXNS ##################

#k_on_c = 4.8e-4
#k_off_c = 2e-3
#k_on_i = 1.8e-4
#k_off_i = 6.6e-3
#k_on_ic = 1.5e-3


# Cap turning on
cap_on = lambda k,t,p,ke,o,l,pr,s,r,nr: (s[0] == 0)*k
model.add_state_reaction(cap_on, k_on_c, rxn_name='mRNA on', inds=[0,1],dstates=[1, 0])

# Cap turning off
cap_off = lambda k,t,p,ke,o,l,pr,s,r,nr: s[0]*k
model.add_state_reaction(cap_off, k_off_c, rxn_name='mRNA off', inds=[0,1],dstates=[-1, 0])

# IRES turning on (cap off)
i_on_c_off = lambda k,t,p,ke,o,l,pr,s,r,nr: (s[1] == 0)*(s[0]==0)*k
model.add_state_reaction(i_on_c_off, k_on_i, rxn_name='i_on_c_off', inds=[0,1], dstates=[0, 1])

# IRES turning off
i_off = lambda k,t,p,ke,o,l,pr,s,r,nr: s[1]*k
model.add_state_reaction(i_off, k_off_i, rxn_name='i_off', inds=[0,1],dstates=[0, -1])

# IRES turning on (cap on)
i_on_c_on = lambda k,t,p,ke,o,l,pr,s,r,nr: (s[1] == 0)*(s[0]==1)*k
model.add_state_reaction(i_on_c_on, k_on_ic, rxn_name='i_on_c_on', inds=[0,1],dstates=[0, 1])


# DEFAULT STEPPING OF ELONGATION USING THE ELONGATION MATRIX
default_step = lambda k,t,p,ke,o,l,pr,s,r,nr:  [(ke[p[i,2], p[i,3]])*(1 - sum(l[p[i,3]+1:p[i,3]+footprint])) for i in range(nr)]
model.add_ribosome_reaction(default_step, 0, rxn_name='elongation', exclusion=1, dloc=1) #default stepping

#initial state
model._state_arr0[0] = 0 #both off
model._state_arr0[1] = 0
# finally specify which reactions are ribosome specific
model._ribosome_reactions = [9]
model._constant_reactions = [0,1,2,3,4,5,6,7,8]

model._lattice_arr0 = np.zeros([model._length+5], dtype=int)


t = np.linspace(0,10000,5001)
if regenerate: 
    #for i in tqdm.tqdm(range(n_model_runs)):
    soln = rsnp.solver.solve_ssa(model, t, n_traj=n_model_runs, burnin=5000, verbose=True)
    if resave:
        soln.save(data_save_folder + 'cap_ires',fmt='.npz')
else:
    soln = rsnp.solver.load_soln(data_save_folder + 'cap_ires.npz')
if resave:
    plt.savefig('%s/cap_ires_model_spots%s'%(figure_folder,figure_format))
    

plot_kymograph(soln, title='CAP-IRES Model', filename='cap_ires_model_kym')
plot_spot_types(soln, n=4, title='CAP-IRES spot types',
                xtick_labels = ['off', 'CAP', 'IRES', 'CAP+IRES'],
                filename='cap_ires_model_kym', int_thresh=5)





